/**
 * A checklist template — the list of things to inspect.
 *
 * Stored as data, never hardcoded in the UI: the day Prevención adds an item,
 * it must reach every phone without a deploy and without reinstalling anything.
 *
 * Templates are versioned and never edited. A new version is a new row, so a
 * signed inspection can be reprinted identically years later.
 */
import { z } from 'zod'

export const templateItemSchema = z.object({
  id: z.string().min(1),
  position: z.number().int().positive(),
  /** '1.1', '1.2', ... Generated by us, contiguous. Never copied from the Excel. */
  code: z.string().regex(/^\d+\.\d+$/),
  label: z.string().min(1),
})

export const templateSectionSchema = z.object({
  id: z.string().min(1),
  position: z.number().int().positive(),
  code: z.string().regex(/^\d+$/),
  title: z.string().min(1),
  items: z.array(templateItemSchema).min(1),
})

export const templateSchema = z.object({
  id: z.string().min(1),
  name: z.string().min(1),
  version: z.number().int().positive(),
  effectiveFrom: z.string().date(),
  /** IndexedDB cannot index booleans — this is 0 | 1 on purpose. */
  isActive: z.union([z.literal(0), z.literal(1)]),
  sections: z.array(templateSectionSchema).min(1),
})

export type TemplateItem = z.infer<typeof templateItemSchema>
export type TemplateSection = z.infer<typeof templateSectionSchema>
export type Template = z.infer<typeof templateSchema>

export const countItems = (template: Template): number =>
  template.sections.reduce((total, section) => total + section.items.length, 0)

export const findItem = (template: Template, itemId: string): TemplateItem | undefined => {
  for (const section of template.sections) {
    const item = section.items.find((i) => i.id === itemId)
    if (item) return item
  }
  return undefined
}
